  ('TL2-23',240,'General','1 2 l e a',' Students equipped with the appropriate individual and group gear',true,true,true,true,true,false)
) as v(code, so, section, element, content, s, o1, o2, a1, a2, a3)
join competencies c on c.code = v.code
on conflict do nothing;

commit;

